const names=['pixelgremlin','duck_enjoyer','critical_miss','sleepy_mage','chaos_goblin','not_a_healer','tiny_tornado','lag_wizard','bread_knight','oops_all_lasers','moonmoth','boss_apologist','purple_potato','bonk_department','snack_attack','spicy_cursor'];
function feed(name,text,system=false){const el=document.createElement('div');el.className='feed-entry'+(system?' system':'');const strong=document.createElement('strong');strong.textContent=name;const time=document.createElement('span');time.className='time';time.textContent=system?'':new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});const p=document.createElement('p');p.textContent=text;el.append(strong,time,p);$('feed').append(el);while($('feed').children.length>55)$('feed').firstChild.remove();$('feed').scrollTop=$('feed').scrollHeight}
