function creditText(choice){return choice?.names.length?'Chosen by '+choice.names.slice(0,2).join(' + ')+(choice.names.length>2?' + '+(choice.names.length-2)+' accomplices':''):choice?.kind==='mutation'?'No votes: Splinter shots selected.':'Chat held the current pattern.'}
