 $('evolutionStrip').hidden=!evolvable;$('evolutionName').textContent=formsFor(recipe.body)[stage].name;$('evolutionStage').textContent='FORM '+['I','II','III'][stage]+' / III';
 const goal=stage<2?evolution.goals[stage]:evolution.goals[1];$('evolutionProgress').textContent=preview?'Art preview · no votes added':stage===2?'FINAL FORM / '+evolution.count+' unique voters':evolution.count+' / '+goal+' unique voters';$('evolutionFill').style.width=(preview?0:Math.min(100,evolution.count/goal*100))+'%';
 if(evolvable&&battle)$('bossName').textContent=formsFor(recipe.body)[battle.evolutionStage].name.toUpperCase();
 for(const id of ['evolutionFirst','evolutionSecond','applyEvolution'])$(id).disabled=active;for(const b of document.querySelectorAll('[data-form]')){b.disabled=phase!=='lobby';b.setAttribute('aria-pressed',String(Number(b.dataset.form)===stage));b.textContent=formsFor(recipe.body)[Number(b.dataset.form)].name}$('previewSpecies').disabled=phase!=='lobby';$('previewSpecies').value=recipe.body;
