 $('pollCount').textContent=poll.votes.size+' votes';$('pollStatus').textContent=roundLive?(live?'Twitch votes only · one per viewer':mutation?'Twitch offline · empty vote selects Splinter shots':'Twitch offline · current attack will be kept'):'Click a command or send a test vote.';
 $('pollClock').textContent=second;$('pollProgress').style.width=(poll.remaining/poll.duration*100)+'%';$('mutationOverlay').hidden=!mutation;$('mutationCountdown').textContent=second;
 if(second!==lastPollSecond){lastPollSecond=second;if(mutation&&second<=3)tone(360+second*90,.09,.025,'triangle')}
 $('timerLabel').textContent=mutation||battle.evolutionRemaining>0?'COMBAT PAUSED':'TIME REMAINING';syncPowers();syncEvolution();
