function handleBattleEvents(){
 for(const e of battle.events){
  if(e==='shoot'){tone(670,.035,.012,'triangle');if(!reduced){const p=battle.player,a=Math.atan2(battle.boss.y-p.y,battle.boss.x-p.x);fx.push({x:p.x+Math.cos(a)*17,y:p.y+Math.sin(a)*17,vx:0,vy:0,color:'#eeffbb',left:.06,max:.06})}}
  if(e==='boss-hit'){tone(180+Math.random()*60,.025,.008,'triangle');burst(battle.boss.x,battle.boss.y,'#d8ff62',4)}
  if(e==='hurt'){tone(95,.15,.04,'sawtooth');announce('HIT! KEEP MOVING',1);shake=reduced?0:5;burst(battle.player.x,battle.player.y,'#ff8ba5',18)}
  // Short visual windups replace advance attack-name popups and warning tones.
  if(e==='warning'&&!reduced)burst(battle.boss.x,battle.boss.y,'#ad8bfa',3);
  if(e==='attack'){shake=reduced?0:3;burst(battle.boss.x,battle.boss.y,'#ff91ad',12);tone(85,.16,.025,'triangle')}
  if(e==='dash'){tone(850,.08,.025);burst(battle.player.x,battle.player.y,'#d8ff62',10)}
  if(e==='evolution'){keys.clear();showEvolution(battle.evolutionStage)}
  if(e==='power-picked'){const power=POWERS.find(p=>p.id===battle.lastPower.id),choice=battle.lastPower;feed('Wildcard / '+power.name,choice.applied?power.help+' '+creditText(choice):'No effect: hearts are full or the round limit was reached.',true);if(choice.applied){burst(battle.boss.x,battle.boss.y,power.team==='STREAMER'?'#d8ff62':'#ff8ba5',18);tone(power.team==='STREAMER'?640:160,.18,.025,'triangle');banner('WILDCARD / '+power.name.toUpperCase(),creditText(choice),1.2)}}
  if(e==='attack-picked'){const choice=battle.lastChoice;banner('CHAT CHOSE '+attackName(choice.id).toUpperCase(),creditText(choice),2);feed('Attack locked',attackName(choice.id)+' / '+creditText(choice),true);syncDirector(true)}
  if(e==='mutation-open'){keys.clear();$('combatBanner').hidden=true;bannerUntil=0;feed('CHAT, MAKE IT WORSE.','Half health! Eight seconds to vote !split, !twin or !haste. Combat and the attack vote are paused.',true);tone(140,.35,.04,'sawtooth');burst(battle.boss.x,battle.boss.y,'#ad8bfa',45);syncDirector(true)}
  if(e==='mutation-applied'){const m=MUTATIONS.find(o=>o.id===battle.mutation);banner('PHASE II / '+m.name.toUpperCase(),m.help,2);feed('Mutation applied',m.name+'. '+m.help+' '+creditText(battle.lastChoice),true);tone(520,.25,.04,'triangle');burst(battle.boss.x,battle.boss.y,'#ffb46d',35);shake=reduced?0:6;syncDirector(true)}
 }
}
function updateCards(){for(const t of TRAITS){const counts=votes.counts(t.key),total=[...votes.votes[t.key].values()].length,winner=votes.winner(t.key);for(const o of t.options){const b=document.querySelector('[data-vote="'+o.id+'"]'),pct=total?Math.round(counts[o.id]/total*100):0;b.classList.toggle('leader',total>0&&winner===o.id);b.querySelector('.percent').textContent=pct+'%';b.querySelector('.fill').style.width=pct+'%';b.setAttribute('aria-label',o.name+', command !'+o.id+', '+counts[o.id]+' votes');b.disabled=phase!=='voting'||live}}
 $('voteTotal').textContent=votes.total+' BUILD VOTES';$('buildHint').textContent=phase==='voting'?'Vote with !commands in chat. Click a choice to test.':phase==='ready'||phase==='fighting'||phase==='results'?'Recipe locked. During combat, use the live command panel.':'One vote per viewer, per trait. Change your mind anytime.';
}
function cast(user,name,text,source='live'){
 if(roundLive&&(!live||source!=='live'))return false;
 if(phase==='fighting'){if(paused||!battle.cast(user,name,text))return false;feed(name,text);syncDirector();return true}
 if(phase!=='voting')return false;if(!votes.cast(user,name,text))return false;feed(name,text);updateCards();recipe=votes.recipe();evolution.record(user);if(EVOLUTION_FORMS[recipe.body]&&evolution.stage>evolutionAnnounced)showEvolution(evolution.stage);syncEvolution();return true;
}
