addEventListener('keydown',e=>{if(e.target.closest('input,textarea,button,dialog'))return;const k=keyName(e);if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Shift','w','a','s','d'].includes(k)){e.preventDefault();keys.add(k)}if(k==='Escape')streamMode(false)});addEventListener('keyup',e=>keys.delete(keyName(e)));addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();if(document.hidden&&phase==='fighting'&&!paused){paused=true;showCaption('PAUSED','Your boss can wait.','The fight paused while this tab was hidden.','Resume fight ↗',()=>{paused=false;$('stageCaption').hidden=true;last=performance.now();canvas.focus()})}});
