function setChatStatus(status,detail){live=status==='connected';const connected=live;$('connect').textContent=connected?'◉ '+detail:'◉ Connect Twitch';$('chatBadge').textContent=connected?'LIVE':status==='connecting'||status==='reconnecting'?'WAIT':'DEMO';$('chatStatus').textContent=connected?'#'+detail:status==='connecting'?'Connecting…':status==='reconnecting'?'Reconnecting…':'Practice lobby';$('disconnect').hidden=!connected;$('authorize').hidden=connected;$('simulation').disabled=connected||['voting','fighting'].includes(phase);$('chatInput').disabled=connected||(['voting','fighting'].includes(phase)&&roundLive);$('voteHint').textContent=connected?'Live votes come only from Twitch accounts.':'Your test votes appear as “you”.';if(connected){if(phase==='voting'&&!roundLive)abortVoting('Twitch connected. Start a fresh round so practice and live votes stay separate.');$('simulation').checked=false;$('modeLabel').textContent='TWITCH CHAT / LIVE';feed('Twitch connected','Now reading votes from #'+detail+'. Simulated and test votes are disabled.',true);if($('connectDialog').open)$('connectDialog').close()}else{if(status==='reconnecting'||status==='error'||status==='disconnected'){if(phase==='fighting'&&roundLive){battle.clearLiveVotes();feed('Live voting interrupted','This ballot was cleared. The existing attack is kept if nobody votes after reconnecting.',true);syncDirector(true)}abortVoting('The Twitch connection dropped. This vote was cancelled so partial votes do not decide the boss.');}$('modeLabel').textContent=roundLive&&phase==='fighting'?'TWITCH OFFLINE / VOTING LOCKED':$('simulation').checked?'SIMULATED CHAT':'MANUAL PRACTICE';if(status==='error'){$('authError').textContent=detail;feed('Connection issue',detail,true)}}updateCards()}
