let hudClock=0;
function simulate(dt){
 if(!$('simulation').checked||roundLive||paused)return;
 demoClock-=dt;if(demoClock>0)return;demoClock=.3+Math.random()*.55;
 const name=names[Math.floor(Math.random()*names.length)];let options;
 if(phase==='fighting')options=battle.poll.kind==='mutation'?battle.poll.options:Math.random()<.5?battle.poll.options:POWERS;else if(phase==='voting')options=TRAITS[Math.floor(Math.random()*3)].options;else return;
 const option=options[Math.floor(Math.random()*options.length)];cast('demo-'+name,name+' [demo]','!'+option.id,'demo');
}
function frame(now){let dt=Math.min(.05,(now-last)/1000);last=now;renderTime=reduced?0:now/1000;
 if(phase==='voting'){const remaining=Math.max(0,(deadline-now)/1000);$('timer').textContent='00:'+String(Math.ceil(remaining)).padStart(2,'0');if(!remaining)lockVotes();else simulate(dt)}
 if(phase==='fighting'&&!paused){battle.step(dt,keys);handleBattleEvents();if(battle.result)endFight();else{simulate(dt);syncDirector()}}
 if(!paused&&evolutionRevealTime>0){evolutionRevealTime=Math.max(0,evolutionRevealTime-dt);syncEvolution()}
 if(phase==='results'){resultsAge+=dt;if(resultsAge<.65&&battle.result.winner==='you'&&!reduced&&Math.random()<.25)burst(battle.boss.x+(Math.random()-.5)*100,battle.boss.y+(Math.random()-.5)*80,'#d8ff62',5)}
 if(!paused){for(const v of fx){v.left-=dt;v.x+=v.vx*dt;v.y+=v.vy*dt;v.vx*=.98;v.vy*=.98}fx=fx.filter(v=>v.left>0);shake=Math.max(0,shake-dt*22)}
 hudClock+=dt;if(hudClock>.08&&battle){hudClock=0;const seconds=Math.ceil(Math.max(0,60-battle.time));$('timer').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('hearts').textContent=Array.from({length:5},(_,i)=>i<battle.player.hp?'●':'○').join(' ');$('bossHp').style.width=(battle.boss.hp/battle.boss.maxHp*100)+'%'}
 if(noticeUntil&&now>noticeUntil){$('fightNotice').textContent='';noticeUntil=0}
 if(bannerUntil&&now>bannerUntil){$('combatBanner').hidden=true;bannerUntil=0}
 draw(renderTime);requestAnimationFrame(frame);
}
